package net.civeira.phylax.feature.oauth.webauthn.application.usecase.finishregistration;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.UUID;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnCredential;
import net.civeira.phylax.feature.oauth.webauthn.domain.exception.WebAuthnException;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnChallengeGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnCredentialGateway;
import net.civeira.phylax.feature.oauth.webauthn.domain.gateway.WebAuthnVerifierGateway;

@ApplicationScoped
@RequiredArgsConstructor
public class FinishRegistrationUsecase {

  private final TenantQueryRepositoryGateway tenants;
  private final UserQueryRepositoryGateway users;
  private final WebAuthnChallengeGateway challengeGateway;
  private final WebAuthnCredentialGateway credentialGateway;
  private final WebAuthnVerifierGateway verifier;

  /**
   * Verifies the browser answer to a registration challenge and stores the new passkey.
   *
   * @param challengeId challenge handed out by the begin step
   * @param tenantName tenant name of the endpoint
   * @param sessionUserUid user of the session that asks: the challenge must belong to that user
   * @param clientCredential the {@code PublicKeyCredential} serialized by the browser
   * @param origin expected browser origin
   * @param rpId relying party id
   * @param deviceName name the user gives to the passkey
   */
  public void finish(String challengeId, String tenantName, String sessionUserUid,
      Map<String, Object> clientCredential, String origin, String rpId, String deviceName) {
    var tenant =
        tenants.find(TenantFilter.builder().name(tenantName).build()).filter(t -> t.isEnabled())
            .orElseThrow(() -> new IllegalArgumentException("tenant " + tenantName));

    String tenantId = tenant.getUid();

    var challenge = challengeGateway.findById(challengeId, tenantId)
        .orElseThrow(WebAuthnException::challengeNotFound);

    if (challenge.isExpired()) {
      throw WebAuthnException.challengeExpired();
    }
    if (!"register".equals(challenge.getType())) {
      throw WebAuthnException.verificationFailed("wrong challenge type");
    }
    if (challenge.isVerified()) {
      throw WebAuthnException.challengeUsed();
    }

    String userUid = challenge.getUserUid()
        .orElseThrow(() -> WebAuthnException.verificationFailed("no user in challenge"));
    if (!userUid.equals(sessionUserUid)) {
      throw WebAuthnException.verificationFailed("challenge of another user");
    }

    var user = users.find(UserFilter.builder().tenant(tenant).uid(userUid).build())
        .orElseThrow(() -> new IllegalArgumentException("user " + userUid));

    Map<String, Object> result =
        verifier.verifyRegistration(clientCredential, challenge.getChallenge(), origin, rpId);

    challengeGateway.markVerified(challenge.markVerified(userUid, user.getName()));

    String loginName = user.getEmail().orElseGet(() -> user.getName());

    @SuppressWarnings("unchecked")
    var transports = result.get("transports") instanceof java.util.List<?>
        ? (java.util.List<String>) result.get("transports")
        : null;

    credentialGateway
        .store(WebAuthnCredential.builder().uid(UUID.randomUUID().toString()).tenantId(tenantId)
            .userUid(userUid).username(loginName).credentialId((String) result.get("credentialId"))
            .publicKey((String) result.get("publicKey"))
            .signCount(((Number) result.get("signCount")).intValue())
            .aaguid((String) result.get("aaguid")).deviceName(deviceName).transports(transports)
            .createdAt(OffsetDateTime.now(ZoneOffset.UTC)).enabled(true).build());
  }
}
